// Replays the Python reference receiver's recorded steps through the JavaScript port and requires
// identical outcomes, statuses and state after every step. The fixture is generated by
// frontend/scripts/receiver_parity.py from tests/motor_receiver.py.

import { readFileSync } from 'node:fs'
import { gunzipSync } from 'node:zlib'
import { describe, expect, it } from 'vitest'
import { MotorReceiver } from './motorReceiver.js'
import { utf8 } from './hmac.js'

const fixture = JSON.parse(gunzipSync(readFileSync(new URL('./__fixtures__/receiver-parity.json.gz', import.meta.url))).toString('utf8'))
const key = utf8(fixture.key)

const padded = (text, bytes) => `${text.slice(0, -1)}, "pad": "${'x'.repeat(bytes)}"}`

function run(rx, op) {
  switch (op.op) {
    case 'begin': return null
    case 'mono': rx.setMonotonic(op.ms); return null
    case 'sensor': rx.setSensor(op.state); return null
    case 'startup': rx.completeStartup(); return null
    case 'ack_cutoff': return rx.acknowledgeCutoff()
    case 'status': return rx.status()
    case 'lose_power': rx.loseMotorPower(); return null
    case 'restore_power': rx.restoreMotorPower(); return null
    case 'freeze': rx.freezeFirmware(); return null
    case 'unfreeze': rx.unfreezeFirmware(); return null
    case 'poll': rx.poll(); return null
    case 'sync': rx.noteVerifiedClock(op.ms); return null
    case 'brownout': rx.brownoutReset(op.nonce); return null
    case 'datagram': return rx.handleRaw(op.pad ? padded(op.raw, op.pad) : op.raw)
    default: throw new Error(`unknown op ${op.op}`)
  }
}

describe('simulator receiver matches the Python reference receiver', () => {
  const total = fixture.scenarios.reduce((n, s) => n + s.steps.length, 0)

  it(`replays ${fixture.scenarios.length} scenarios, ${total} steps, with identical results`, () => {
    let checked = 0
    fixture.scenarios.forEach((scenario, s) => {
      const rx = new MotorReceiver(scenario.boot_nonce, { key, controllerId: fixture.controller_id })
      const expected = {}
      scenario.steps.forEach((step, i) => {
        const where = `scenario ${s}, step ${i}, op ${JSON.stringify(step.op).slice(0, 200)}`
        const result = run(rx, step.op)
        Object.assign(expected, step.changes)
        // Compare in one go but with a location, so a failure says exactly where the two differ.
        const actual = { result, snapshot: rx.snapshot(), torque: rx.motorsHaveTorque() }
        const wanted = { result: step.result, snapshot: expected, torque: step.torque }
        if (JSON.stringify(actual) !== JSON.stringify(wanted)) {
          expect(actual, where).toEqual(wanted)
        }
        checked += 1
      })
    })
    expect(checked).toBe(total)
  })

  it('exercises every outcome of the receiver procedure', () => {
    const outcomes = new Set()
    for (const scenario of fixture.scenarios) {
      for (const step of scenario.steps) if (step.op.op === 'datagram') outcomes.add(step.result)
    }
    expect([...outcomes].sort()).toEqual([
      'accepted_motion', 'accepted_rearm', 'accepted_start', 'accepted_stop', 'expired_stop', 'frozen',
      'ignored', 'invalid_stop', 'malformed', 'rejected_motion', 'rejected_rearm', 'stale_stop',
    ])
  })
})
